import type { ReactNode } from 'react';
import { cx } from '@/lib/cx';
import { Card } from './card';
import './stat-s1.css';

/**
 * B3 · StatS1 — the signature stat, the ONLY KPI card. Three required
 * zones: mono label + delta / icon tile + value / hairline footnote that
 * says something NOT already in the card. Answers "how much, and so what."
 */
export interface StatS1Props {
  /** Mono micro label, e.g. "REVENUE · MTD". */
  label: string;
  /** The value as display text, e.g. "$482,190". */
  value: string;
  /** Unit suffix rendered soft at 14px, e.g. "%", "pt", "d". */
  unit?: string;
  /** Signed delta, e.g. +12.4 renders "▲ 12.4%". Omit when no comparison exists. */
  delta?: number;
  /** How the delta is formatted; default appends "%". */
  deltaSuffix?: string;
  /** 16px stroke icon, rendered in a 34px seed-tint tile. */
  icon: ReactNode;
  /** Footnote: MUST contain information not already in the card
      (target, exposure, oldest age…). The load-bearing figure in <b>. */
  footnote: ReactNode;
  /** Plain-language footnote for the aria-label (screen readers). */
  footnoteText?: string;
  className?: string;
}

export function StatS1({
  label,
  value,
  unit,
  delta,
  deltaSuffix = '%',
  icon,
  footnote,
  footnoteText,
  className,
}: StatS1Props) {
  const deltaText =
    delta === undefined ? '' : `${delta >= 0 ? 'up' : 'down'} ${Math.abs(delta)}${deltaSuffix}`;
  const ariaLabel = [`${label}: ${value}${unit ?? ''}`, deltaText, footnoteText]
    .filter(Boolean)
    .join(', ');

  return (
    <Card className={cx('sv-stat', className)} aria-label={ariaLabel} role="group">
      <div aria-hidden="true">
        <div className="sv-stat__top">
          <span className="sv-stat__label sv-mono">{label}</span>
          {delta !== undefined && (
            <span className={cx('sv-stat__delta sv-num', delta >= 0 ? 'sv-stat__delta--ok' : 'sv-stat__delta--bad')}>
              {delta >= 0 ? '▲' : '▼'} {Math.abs(delta)}
              {deltaSuffix}
            </span>
          )}
        </div>
        <div className="sv-stat__mid">
          <span className="sv-stat__tile">{icon}</span>
          <span className="sv-stat__value sv-num">
            {value}
            {unit && <span className="sv-stat__unit">{unit}</span>}
          </span>
        </div>
        <div className="sv-stat__foot">{footnote}</div>
      </div>
    </Card>
  );
}

/* B3 · StatS1 */

@layer sv-components {
  .sv-stat__top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 18px 0;
  }

  .sv-stat__label {
    color: var(--sv-ink-soft);
  }

  .sv-stat__delta {
    font-size: 12px;
    font-weight: 700;
  }

  .sv-stat__delta--ok  { color: var(--sv-ok); }
  .sv-stat__delta--bad { color: var(--sv-bad); }

  .sv-stat__mid {
    display: flex;
    align-items: center;
    gap: var(--sv-s3);
    padding: var(--sv-s2) 18px 14px;
  }

  .sv-stat__tile {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border-radius: var(--sv-r);
    background: var(--sv-seed-tint);
    color: var(--sv-seed);
  }

  .sv-stat__tile svg {
    width: 16px;
    height: 16px;
  }

  .sv-stat__value {
    font-size: 24px;
    line-height: 1.1;
    font-weight: 800;
    letter-spacing: -0.025em;
  }

  .sv-stat__unit {
    margin-left: 2px;
    font-size: 14px;
    font-weight: 600;
    color: var(--sv-ink-soft);
    letter-spacing: 0;
  }

  .sv-stat__foot {
    padding: 10px 18px 12px;
    border-top: 1px solid var(--sv-line);
    font-size: 11.5px;
    color: var(--sv-ink-soft);
  }

  .sv-stat__foot b {
    font-weight: 600;
    color: var(--sv-ink);
  }
}

import type { HTMLAttributes, ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './card.css';

/**
 * Card — the paper primitive every widget sits on. Exactly one
 * --sv-shadow, radius --sv-r, background --sv-paper, zero border (A4).
 * Not a widget type itself: widgets (S1, Trend, DataTable…) compose it.
 */
export interface CardProps extends HTMLAttributes<HTMLElement> {
  as?: 'div' | 'section' | 'article';
}

export function Card({ as: Tag = 'section', className, children, ...rest }: CardProps) {
  return (
    <Tag {...rest} className={cx('sv-card', className)}>
      {children}
    </Tag>
  );
}

/**
 * The universal card head (Law: bold title + faint subtitle left, one
 * seed text-link action right — never icon-only mystery menus).
 */
export interface CardHeadProps {
  title: string;
  subtitle?: string;
  /** One action, rendered right. Use ButtonLink or a mono range control. */
  action?: ReactNode;
  className?: string;
}

export function CardHead({ title, subtitle, action, className }: CardHeadProps) {
  return (
    <header className={cx('sv-card__head', className)}>
      <div>
        <h3 className="sv-card__title">{title}</h3>
        {subtitle && <p className="sv-card__subtitle">{subtitle}</p>}
      </div>
      {action && <div className="sv-card__action">{action}</div>}
    </header>
  );
}

/* Card — the paper primitive (A4: one shadow, one radius, no border) */

@layer sv-components {
  .sv-card {
    background: var(--sv-paper);
    border-radius: var(--sv-r);
    box-shadow: var(--sv-shadow);
  }

  .sv-card__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--sv-s4);
    padding: var(--sv-s4) 18px var(--sv-s3);
  }

  .sv-card__title {
    font-size: 13.5px;
    font-weight: 700;
  }

  .sv-card__subtitle {
    margin-top: 2px;
    font-size: 11.5px;
    font-weight: 400;
    color: var(--sv-ink-faint);
  }

  .sv-card__action {
    flex-shrink: 0;
    padding-top: 2px;
  }
}
